package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	msg := b.String()
	n := len(msg)
	if n == 0 {
		return ""
	}
	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c
	var out strings.Builder
	for col := 0; col < c; col++ {
		if col > 0 {
			out.WriteByte(' ')
		}
		for row := 0; row < r; row++ {
			idx := row*c + col
			if idx < n {
				out.WriteByte(msg[idx])
			} else {
				out.WriteByte(' ')
			}
		}
	}
	return out.String()
}
```

